package com.ruoyi.metal.service;
import java.util.*;
import com.ruoyi.common.exception.ServiceException;
import com.ruoyi.common.utils.SecurityUtils;
import com.ruoyi.metal.security.FactoryScope;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import static com.ruoyi.metal.service.StorageSupport.*;

@Service
public class ProductionBatchTraceService {
 private final JdbcTemplate jdbc;private final FactoryScope scope;
 public ProductionBatchTraceService(JdbcTemplate jdbc,FactoryScope scope){this.jdbc=jdbc;this.scope=scope;}
 @Transactional(readOnly=true)
 public Map<String,Object> trace(long batch,Long requested,String direction,int size,String cursor){allow(scope,"metal:work-order:query");long f=scope.resolveFactory(requested);if(!Set.of("BOTH","UPSTREAM","DOWNSTREAM").contains(direction)||size<1||size>100)throw fail("追溯方向或分页大小无效");long after=cursor==null||cursor.isBlank()?0:id(cursor);long item=id(one(jdbc,"SELECT order_item_id FROM metal_production_batch WHERE factory_id=? AND id=?",f,batch).get("order_item_id"));
 var all=jdbc.queryForList("SELECT CAST(e.id AS CHAR) id,CAST(e.operation_id AS CHAR) operationId,CAST(e.source_batch_id AS CHAR) sourceBatchId,CAST(e.target_batch_id AS CHAR) targetBatchId,e.planned_quantity_part plannedQuantityPart,CAST(e.weight AS CHAR) weight,e.quantity,e.measurement_mode measurementMode,e.allocation_basis allocationBasis,o.action,EXISTS(SELECT 1 FROM metal_production_execution_operation r WHERE r.factory_id=e.factory_id AND r.reversal_of=e.operation_id) reversed FROM metal_production_batch_edge e JOIN metal_production_execution_operation o ON o.factory_id=e.factory_id AND o.id=e.operation_id JOIN metal_production_batch b ON b.factory_id=e.factory_id AND b.id=e.source_batch_id WHERE e.factory_id=? AND b.order_item_id=? ORDER BY e.id LIMIT 10001",f,item);if(all.size()>10000)throw new ServiceException("追溯关系超出本次查询上限，请按工单核对",409);
 var visited=new LinkedHashSet<Long>();visited.add(batch);boolean changed;do{changed=false;for(var edge:all){long from=id(edge.get("sourceBatchId")),to=id(edge.get("targetBatchId"));if(!"UPSTREAM".equals(direction)&&visited.contains(from))changed|=visited.add(to);if(!"DOWNSTREAM".equals(direction)&&visited.contains(to))changed|=visited.add(from);}}while(changed);
 var matching=all.stream().filter(e->visited.contains(id(e.get("sourceBatchId")))&&visited.contains(id(e.get("targetBatchId")))&&id(e.get("id"))>after).toList();boolean more=matching.size()>size;var edges=matching.stream().limit(size).toList();var pageNodes=new TreeSet<Long>();pageNodes.add(batch);for(var e:edges){pageNodes.add(id(e.get("sourceBatchId")));pageNodes.add(id(e.get("targetBatchId")));}var nodes=new ArrayList<Map<String,Object>>();var executions=new ArrayList<Map<String,Object>>();var allocations=new ArrayList<Map<String,Object>>();var operations=new LinkedHashMap<Long,Map<String,Object>>();var productionEvents=new ArrayList<Map<String,Object>>();var storageEvents=new LinkedHashMap<String,Map<String,Object>>();var documents=new LinkedHashMap<String,Map<String,Object>>();var stockSlices=new ArrayList<Map<String,Object>>();var materialSources=new ArrayList<Map<String,Object>>();for(long bid:pageNodes){productionEvents.addAll(jdbc.queryForList("SELECT CAST(ev.id AS CHAR) id,CAST(ev.execution_id AS CHAR) executionId,CAST(e.batch_id AS CHAR) batchId,CAST(ev.document_id AS CHAR) documentId,CAST(ev.line_id AS CHAR) lineId,ev.event_type eventType,CAST(ev.stock_id AS CHAR) stockId,CAST(ev.weight AS CHAR) weight,ev.quantity,ev.reversed FROM metal_production_execution_event ev JOIN metal_production_execution e ON e.factory_id=ev.factory_id AND e.id=ev.execution_id WHERE e.factory_id=? AND e.batch_id=? ORDER BY ev.id",f,bid));stockSlices.addAll(jdbc.queryForList("SELECT CAST(sl.id AS CHAR) stockSliceId,CAST(sl.batch_id AS CHAR) batchId,CAST(sl.stock_id AS CHAR) stockId,st.batch_no stockNumber,(SELECT b.number FROM metal_production_batch b WHERE b.factory_id=sl.factory_id AND b.id=sl.batch_id) batchNumber,CAST(st.origin_document_id AS CHAR) originDocumentId,CAST(st.origin_line_id AS CHAR) originLineId,CAST(st.origin_step_id AS CHAR) originStepId,CAST(sl.weight AS CHAR) weight,sl.quantity,sl.version FROM metal_storage_batch_slice sl JOIN metal_storage_stock st ON st.factory_id=sl.factory_id AND st.id=sl.stock_id WHERE sl.factory_id=? AND sl.batch_id=? ORDER BY sl.id",f,bid));materialSources.addAll(jdbc.queryForList("SELECT CAST(ms.id AS CHAR) sourceAllocationId,CAST(ms.source_allocation_id AS CHAR) parentSourceAllocationId,CAST(ms.stock_slice_id AS CHAR) stockSliceId,CAST(ms.execution_id AS CHAR) executionId,CAST(ms.root_issue_allocation_id AS CHAR) rootIssueAllocationId,CAST(a.line_id AS CHAR) issueLineId,CAST(a.document_id AS CHAR) issueDocumentId,CAST(a.stock_id AS CHAR) issueStockId,st.batch_no issueStockNumber,CAST(st.origin_document_id AS CHAR) issueOriginDocumentId,CAST(st.origin_line_id AS CHAR) issueOriginLineId,ms.source_kind sourceKind,CAST(ms.source_owner_id AS CHAR) sourceOwnerId,CAST(ms.current_owner_id AS CHAR) currentOwnerId,CAST(ms.weight AS CHAR) weight,ms.quantity FROM metal_production_material_source ms LEFT JOIN metal_storage_issue_allocation a ON a.factory_id=ms.factory_id AND a.id=ms.root_issue_allocation_id LEFT JOIN metal_storage_stock st ON st.factory_id=a.factory_id AND st.id=a.stock_id LEFT JOIN metal_storage_batch_slice sl ON sl.factory_id=ms.factory_id AND sl.id=ms.stock_slice_id LEFT JOIN metal_production_execution e ON e.factory_id=ms.factory_id AND e.id=ms.execution_id WHERE ms.factory_id=? AND (sl.batch_id=? OR e.batch_id=?) ORDER BY ms.id",f,bid,bid));for(var se:jdbc.queryForList("SELECT CAST(se.id AS CHAR) id,CAST(se.document_id AS CHAR) documentId,CAST(se.line_id AS CHAR) lineId,CAST(se.stock_slice_id AS CHAR) stockSliceId,se.action,CAST(se.reversed_by AS CHAR) reversedBy,CAST(se.result AS CHAR) result FROM metal_storage_event se LEFT JOIN metal_storage_batch_slice sl ON sl.factory_id=se.factory_id AND sl.id=se.stock_slice_id LEFT JOIN metal_storage_document d ON d.factory_id=se.factory_id AND d.id=se.document_id WHERE se.factory_id=? AND (sl.batch_id=? OR d.batch_id=? OR EXISTS(SELECT 1 FROM metal_storage_batch_slice_entry entry JOIN metal_storage_batch_slice part ON part.factory_id=entry.factory_id AND part.id=entry.stock_slice_id WHERE entry.factory_id=se.factory_id AND entry.event_id=se.id AND part.batch_id=?)) ORDER BY se.id",f,bid,bid,bid))storageEvents.put(text(se.get("id")),se);nodes.add(one(jdbc,"SELECT CAST(id AS CHAR) id,CAST(id AS CHAR) batchId,number,lifecycle,planned_quantity plannedQuantity,version,CAST(completed_step_ids AS CHAR) completedStepIds FROM metal_production_batch WHERE factory_id=? AND id=?",f,bid));executions.addAll(jdbc.queryForList("SELECT CAST(id AS CHAR) executionId,CAST(batch_id AS CHAR) batchId,CAST(order_step_id AS CHAR) orderStepId,status,version,CAST(input_weight AS CHAR) inputWeight,CAST(output_weight AS CHAR) outputWeight,CAST(carry_in_weight AS CHAR) carryInWeight,CAST(carry_out_weight AS CHAR) carryOutWeight FROM metal_production_execution WHERE factory_id=? AND batch_id=? ORDER BY id",f,bid));}
 for(var edge:edges){long op=id(edge.get("operationId"));if(operations.containsKey(op))continue;var row=one(jdbc,"SELECT CAST(o.id AS CHAR) operationId,o.action,o.reason,DATE_FORMAT(o.create_time,'%Y-%m-%dT%H:%i:%s+08:00') createdAt,(SELECT CAST(r.id AS CHAR) FROM metal_production_execution_operation r WHERE r.factory_id=o.factory_id AND r.reversal_of=o.id LIMIT 1) reversedBy FROM metal_production_execution_operation o WHERE o.factory_id=? AND o.id=?",f,op);if(scope.isAdmin()||SecurityUtils.hasPermi("metal:production-batch:reverse")){var ctx=new ProductionBatchReverseService(jdbc,scope).context(op,f);row.put("canReverse",ctx.get("allowed"));row.put("reverseDisabledReason",String.join("；",(List<String>)ctx.get("blockingReasons")));}else{row.put("canReverse",false);row.put("reverseDisabledReason","没有拆合撤销权限");}operations.put(op,row);allocations.addAll(jdbc.queryForList("SELECT CAST(id AS CHAR) allocationId,CAST(operation_id AS CHAR) operationId,CAST(from_source_id AS CHAR) fromSourceId,CAST(to_source_id AS CHAR) toSourceId,purpose,CAST(weight AS CHAR) weight,quantity,allocation_basis allocationBasis FROM metal_production_material_allocation WHERE factory_id=? AND operation_id=? ORDER BY id",f,op));}
 for(var original:new ArrayList<>(operations.values()))if(original.get("reversedBy")!=null){long reverse=id(original.get("reversedBy"));var op=one(jdbc,"SELECT CAST(id AS CHAR) operationId,action,reason,CAST(actor_id AS CHAR) actorId,CAST(reversal_of AS CHAR) reversalOf,DATE_FORMAT(create_time,'%Y-%m-%dT%H:%i:%s+08:00') createdAt FROM metal_production_execution_operation WHERE factory_id=? AND id=?",f,reverse);op.put("canReverse",false);op.put("reverseDisabledReason","反向操作保留用于审计，不重复撤销");operations.put(reverse,op);allocations.addAll(jdbc.queryForList("SELECT CAST(id AS CHAR) allocationId,CAST(operation_id AS CHAR) operationId,CAST(from_source_id AS CHAR) fromSourceId,CAST(to_source_id AS CHAR) toSourceId,purpose,CAST(weight AS CHAR) weight,quantity,allocation_basis allocationBasis FROM metal_production_material_allocation WHERE factory_id=? AND operation_id=? ORDER BY id",f,reverse));}
 var sourceLines=new LinkedHashSet<List<Long>>();for(var source:materialSources){if(source.get("issueDocumentId")!=null&&source.get("issueLineId")!=null)sourceLines.add(List.of(id(source.get("issueDocumentId")),id(source.get("issueLineId"))));if(source.get("issueOriginDocumentId")!=null&&source.get("issueOriginLineId")!=null)sourceLines.add(List.of(id(source.get("issueOriginDocumentId")),id(source.get("issueOriginLineId"))));}
 for(var line:sourceLines)for(var event:jdbc.queryForList("SELECT CAST(id AS CHAR) id,CAST(document_id AS CHAR) documentId,CAST(line_id AS CHAR) lineId,CAST(stock_slice_id AS CHAR) stockSliceId,action,CAST(reversed_by AS CHAR) reversedBy,CAST(result AS CHAR) result FROM metal_storage_event WHERE factory_id=? AND document_id=? AND line_id=? ORDER BY id",f,line.get(0),line.get(1)))storageEvents.put(text(event.get("id")),event);
 for(var original:new ArrayList<>(storageEvents.values()))if(original.get("reversedBy")!=null)for(var event:jdbc.queryForList("SELECT CAST(id AS CHAR) id,CAST(document_id AS CHAR) documentId,CAST(line_id AS CHAR) lineId,CAST(stock_slice_id AS CHAR) stockSliceId,action,CAST(reversed_by AS CHAR) reversedBy,CAST(result AS CHAR) result FROM metal_storage_event WHERE factory_id=? AND document_id=? AND line_id=? ORDER BY id",f,id(original.get("reversedBy")),id(original.get("lineId"))))storageEvents.put(text(event.get("id")),event);
 for(var se:storageEvents.values()){long did=id(se.get("documentId"));var doc=one(jdbc,"SELECT CAST(id AS CHAR) id,number,type,status,CAST(batch_id AS CHAR) batchId,CAST(execution_id AS CHAR) executionId,version FROM metal_storage_document WHERE factory_id=? AND id=?",f,did);documents.put(text(doc.get("id")),doc);}var result=new LinkedHashMap<String,Object>();result.put("batchId",String.valueOf(batch));result.put("direction",direction);result.put("nodes",nodes);result.put("edges",edges);result.put("executions",executions);result.put("allocations",allocations);result.put("productionEvents",productionEvents);result.put("storageEvents",new ArrayList<>(storageEvents.values()));result.put("documents",new ArrayList<>(documents.values()));result.put("stockSlices",stockSlices);result.put("materialSources",materialSources);result.put("operations",new ArrayList<>(operations.values()));result.put("nextCursor",more?edges.get(edges.size()-1).get("id"):null);result.put("truncated",more);return result;
 }
}


